function togglePause(){paused=!paused;$('pauseShade').hidden=!paused;$('pauseBtn').textContent=paused?'▶ 계속하기':'Ⅱ 일시 정지';}
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Tab','F2','F3'].includes(e.key))e.preventDefault();if(e.key==='Escape'){mode=null;panel='main';page=0;drag=null;signature='';updateUI();return;}if(e.repeat)return;if(e.key==='F2'){openPractice();return;}if(e.key==='F3'){openCodex();return;}if(e.key===' '){centerBase();return;}if(e.key==='Tab'){page++;if(page>=Math.ceil(commandsFor(sel()[0]).length/9))page=0;signature='';updateUI();return;}if(/^[1-9]$/.test(e.key)){e.preventDefault();if(e.ctrlKey||e.metaKey){groups[e.key]=[...selected];toast(`부대 ${e.key} 지정 · ${selected.length}개`);}else if(groups[e.key])select(groups[e.key].filter(id=>engine.get(id)));return;}if(e.key.toLowerCase()==='p'){togglePause();return;}const b=[...$('commands').querySelectorAll('[data-key]')].find(b=>b.dataset.key.toLowerCase()===e.key.toLowerCase());if(b){e.preventDefault();command(b.dataset.command);return;}if(e.key.startsWith('Arrow'))keys[e.key]=true;});document.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};drag=null;mouse.inside=false;save();});
$('mainTab').onclick=()=>showPanel('main');$('skillTab').onclick=()=>showPanel('skills');$('techTab').onclick=()=>showPanel('tech');$('prevPage').onclick=()=>{page--;signature='';updateUI();};$('nextPage').onclick=()=>{page++;signature='';updateUI();};$('cancelQueue').onclick=()=>{if(ownSel()[0])result(engine.cancel(ownSel()[0].id));};$('centerBtn').onclick=centerBase;$('pauseBtn').onclick=togglePause;$('speedBtn').onclick=()=>{speed=speed===1?2:speed===2?.5:1;$('speedBtn').textContent=speed+'× 속도';};$('dismissHint').onclick=()=>$('introHint').hidden=true;
$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').classList.toggle('sound-on',sound);$('soundBtn').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');beep();};$('helpBtn').onclick=()=>{keys={};$('helpDialog').showModal();};$('menuBtn').onclick=()=>{keys={};$('resetConfirm').hidden=true;$('saveInfo').textContent=`${races[engine.state.race].name} · 종족별 저장 · 기존 v1 저장은 보존됩니다.`;$('menuDialog').showModal();};document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('saveBtn').onclick=()=>{save(false);$('menuDialog').close();};$('loadBtn').onclick=()=>{if(loadRace(engine.state.race))$('menuDialog').close();else toast('불러올 저장 기록이 없습니다.',true);};$('newBtn').onclick=()=>$('resetConfirm').hidden=false;$('cancelNew').onclick=()=>$('resetConfirm').hidden=true;$('confirmNew').onclick=()=>{$('menuDialog').close();openRace(true);};
function openRace(fresh=false){save();freshGame=fresh;chosenRace=engine.state.race;$('raceNote').textContent=fresh?'선택한 종족의 저장 기지를 새 게임으로 덮어씁니다. 다른 종족의 저장은 유지됩니다.':'종족별로 진행 상황이 따로 저장됩니다. 저장한 기지는 이어서 플레이합니다.';$('raceCards').innerHTML=Object.entries(races).map(([id,r])=>`<button data-race="${id}" class="race-card ${id===chosenRace?'selected':''}" style="--race-color:${r.color}"><span class="race-emblem">${id==='terran'?'▰':id==='zerg'?'♜':'◇'}</span><span class="eyebrow">${r.en}</span><strong>${r.name}</strong><small>${r.desc}</small></button>`).join('');$('raceCards').querySelectorAll('button').forEach(b=>b.onclick=()=>{chosenRace=b.dataset.race;$('raceCards').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));});$('raceDialog').showModal();}
$('raceBtn').onclick=()=>openRace();$('confirmRace').onclick=()=>{if(freshGame||!loadRace(chosenRace,true)){bindEngine(new FrontierEngine(chosenRace));camera.z=clamp(view.h/500,.62,1);centerBase();$('introHint').hidden=false;}save();$('raceDialog').close();updateUI();};
function populateSpawns(){const race=$('enemyRace').value;$('spawnType').innerHTML='<option value="">혼합 부대</option>'+Object.entries(U).filter(([id,t])=>t.race===race&&!t.hiddenUnit&&id!=='larva').map(([id,t])=>`<option value="${id}">${t.name}${t.building?' (건물)':''}</option>`).join('');}
function openPractice(){keys={};const s=engine.state;$('enemyRace').value=s.practice.race;$('aggressiveCheck').checked=s.practice.aggressive;for(const [id,key]of[['freeTechCheck','freeTech'],['godCheck','invincible'],['resourceCheck','infiniteResources'],['fogCheck','fog']])$(id).checked=s.settings[key];$('waveBtn').textContent=s.practice.waves?'연속 웨이브 중지':'연속 웨이브 시작';populateSpawns();$('practiceDialog').showModal();}
$('practiceBtn').onclick=openPractice;$('enemyRace').onchange=()=>{engine.state.practice.race=$('enemyRace').value;populateSpawns();};$('aggressiveCheck').onchange=()=>engine.state.practice.aggressive=$('aggressiveCheck').checked;$('spawnBtn').onclick=()=>{mode={kind:'spawn',info:{race:$('enemyRace').value,side:$('spawnSide').value,type:$('spawnType').value,count:Number($('spawnCount').value),aggressive:$('aggressiveCheck').checked}};$('practiceDialog').close();updateUI();};$('waveBtn').onclick=()=>{engine.state.practice.waves=!engine.state.practice.waves;engine.state.practice.race=$('enemyRace').value;engine.state.practice.timer=5;$('waveBtn').textContent=engine.state.practice.waves?'연속 웨이브 중지':'연속 웨이브 시작';toast(engine.state.practice.waves?'5초 후 첫 웨이브가 시작됩니다.':'웨이브를 중지했습니다.');};$('clearEnemies').onclick=()=>{engine.own(1).forEach(e=>engine.kill(e,null,true));engine.state.practice.waves=false;$('waveBtn').textContent='연속 웨이브 시작';toast('적군을 제거했습니다.');};$('grantResources').onclick=()=>{engine.state.minerals+=10000;engine.state.gas+=10000;toast('미네랄과 가스를 10,000씩 추가했습니다.');updateUI();};for(const [id,key]of[['freeTechCheck','freeTech'],['godCheck','invincible'],['resourceCheck','infiniteResources'],['fogCheck','fog']])$(id).onchange=()=>{engine.state.settings[key]=$(id).checked;signature='';};
function openCodex(){$('codexRace').value=engine.state.race;$('codexSearch').value='';renderCodex();$('codexDialog').showModal();}
function renderCodex(){const race=$('codexRace').value,search=$('codexSearch').value.trim().toLowerCase(),list=Object.entries(U).filter(([id,t])=>t.race===race&&!t.hiddenUnit&&(t.name.toLowerCase().includes(search)||t.skills.some(id=>A[id].name.includes(search)))),cards=[];for(const [id,t]of list){cards.push(`<article class="codex-card"><img alt="" src="${iconURL(id)}"><div><span class="eyebrow">${t.building?'STRUCTURE':t.fly?'AIR UNIT':'GROUND UNIT'}</span><h3>${t.name}</h3><p>체력 ${t.hp}${t.shield?' · 실드 '+t.shield:''} · ◆ ${t.min} / ◈ ${t.gas}${!t.building?' · 보급 '+t.supply:''}</p>${t.damage||t.airDamage?`<p>공격 ${t.damage||t.airDamage} · 사거리 ${t.range} · ${t.air&&t.ground?'지상 / 공중':t.air?'공중':'지상'}</p>`:''}<p class="codex-requires">${t.requires.length?'필요: '+t.requires.map(x=>U[x].name).join(' · '):'기본 기술'}${t.morphFrom?' · 변태: '+U[t.morphFrom].name:''}${t.mergeFrom?' · 합체: '+U[t.mergeFrom].name+' 2기':''}</p>${t.skills.map(x=>`<div class="codex-skill"><b>${A[x].name}</b><span>${A[x].desc}</span></div>`).join('')}${t.produces?.length?`<p>생산: ${t.produces.map(x=>U[x].name).join(', ')}</p>`:''}${t.research?.length?`<p>연구: ${t.research.map(x=>R[x].name).join(', ')}</p>`:''}</div></article>`);} $('codexContent').innerHTML=cards.join('');$('codexCount').textContent=list.length+'개 항목';}
$('codexBtn').onclick=openCodex;$('codexRace').onchange=renderCodex;$('codexSearch').oninput=renderCodex;$('fullBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('app').requestFullscreen();}catch{toast('전체 화면을 사용할 수 없습니다.',true);}};
