initialLoad();if(hasLoaded)$('introHint').hidden=true;resize();if(!hasLoaded){camera.z=clamp(view.h/500,.62,1);centerBase();}new ResizeObserver(resize).observe($('battlefield'));window.addEventListener('beforeunload',()=>save());requestAnimationFrame(loop);window.Frontier={version:'2.0.0',getState:()=>JSON.parse(engine.serialize()).state,getSelection:()=>[...selected],getCamera:()=>({...camera})};
